// logins_by_keys returns the rows with the keys `keys`, in their order.
fn (g Graph) logins_by_keys(keys []string) ![]LoginNode {
	rows := g.logins().where(load.in_keys('id', keys, .int)).all()!
	mut by_key := map[string]LoginNode{}
	for row in rows {
		by_key[row.login.id.str()] = row
	}
	mut found := []LoginNode{cap: keys.len}
	for key in keys {
		found << by_key[key] or {
			return NotFoundError{
				table: 'logins'
			}
		}
	}
	return found
}
